'use client'

import type { ComponentProps } from 'react'
import {
  HoverCard as UiHoverCard,
  HoverCardArrow as UiHoverCardArrow,
  HoverCardContent as UiHoverCardContent,
  HoverCardTrigger as UiHoverCardTrigger,
} from '@ui-sdk/react/hover-card'

import './hover-card.css'

function omit<T extends object, const K extends readonly (keyof T)[]>(
  obj: T,
  ...keys: K
): Omit<T, K[number]> {
  const copy = { ...obj }
  for (const key of keys) delete copy[key]
  return copy
}

/**
 * HoverCard, a 1:1 port of opencode's HoverCard (`@opencode/ui`, MIT):
 * `packages/ui/src/components/hover-card.css`, on top of ui-sdk's headless
 * HoverCard.
 *
 * Styling lives in `hover-card.css` as attribute rules (`data-open`,
 * `data-closed`), so the card's surface, its 4px inset and its two 150ms
 * scale animations match `data-component="hover-card-content"`. Behaviour (the
 * pointer and focus delays, staying open while the pointer crosses the gap,
 * flipping and shifting, the arrow's offset, Escape, ARIA wiring) comes from
 * `@ui-sdk/react`.
 *
 * Upstream's trigger is a plain wrapper div with `tabIndex={-1}`. ui-sdk's
 * trigger is the link itself, so give it an `href`: it opens the card on hover
 * and focus and still follows the link on press.
 *
 * Upstream wraps the children in a `data-slot="hover-card-body"` div with the
 * 4px inset. ui-sdk's content holds the children directly, so the content
 * carries that inset as its own padding.
 *
 * Upstream has no arrow part; ui-sdk's `HoverCardArrow` renders an empty div
 * that this port leaves unstyled.
 */

type UiHoverCardProps = ComponentProps<typeof UiHoverCard>

export type HoverCardProps = UiHoverCardProps

export function HoverCard(props: HoverCardProps) {
  return <UiHoverCard {...props} />
}

type UiHoverCardTriggerProps = ComponentProps<typeof UiHoverCardTrigger>

export type HoverCardTriggerProps = Omit<
  UiHoverCardTriggerProps,
  'className' | 'render'
> & {
  className?: UiHoverCardTriggerProps['className']
  render?: UiHoverCardTriggerProps['render']
}

export function HoverCardTrigger(props: HoverCardTriggerProps) {
  const rest = omit(props, 'className', 'render')

  return (
    <UiHoverCardTrigger {...rest} className={props.className} render={props.render} />
  )
}

type UiHoverCardContentProps = ComponentProps<typeof UiHoverCardContent>

export type HoverCardContentProps = Omit<
  UiHoverCardContentProps,
  'className' | 'render'
> & {
  className?: UiHoverCardContentProps['className']
  render?: UiHoverCardContentProps['render']
}

export function HoverCardContent(props: HoverCardContentProps) {
  const rest = omit(props, 'className', 'render')

  return (
    <UiHoverCardContent {...rest} className={props.className} render={props.render} />
  )
}

type UiHoverCardArrowProps = ComponentProps<typeof UiHoverCardArrow>

export type HoverCardArrowProps = Omit<
  UiHoverCardArrowProps,
  'className' | 'render'
> & {
  className?: UiHoverCardArrowProps['className']
  render?: UiHoverCardArrowProps['render']
}

export function HoverCardArrow(props: HoverCardArrowProps) {
  const rest = omit(props, 'className', 'render')

  return <UiHoverCardArrow {...rest} className={props.className} render={props.render} />
}

/*
 * 1:1 port of opencode's HoverCard (`@opencode/ui`, MIT):
 * packages/ui/src/components/hover-card.css.
 *
 * Only the selectors changed, to meet ui-sdk's markup. Every value is
 * upstream, so the card, its inset and its 150ms scale animations match
 * `data-component="hover-card-content"`:
 *
 *   [data-slot="hover-card-trigger"]      →  same (ui-sdk's trigger slot)
 *   [data-component="hover-card-content"]  →  [data-slot="hover-card-content"]
 *   [data-slot="hover-card-body"]          →  no element; ui-sdk's content holds
 *                                             the body, so its 4px inset and
 *                                             `overflow: hidden` are the
 *                                             content's
 *   [data-expanded]                        →  [data-open]  (ui-sdk's attribute)
 *   [data-closed]                          →  same, and also
 *                                             [data-ending-style], the state
 *                                             ui-sdk keeps while an exit
 *                                             animation runs
 *   --kb-hovercard-content-transform-origin →  --transform-origin
 *
 * Two upstream app-level tokens are mapped to the --v2-* token that is
 * nearest, noted at each use: --surface-raised-stronger-non-alpha and
 * --shadow-md, as in popover and tooltip. Upstream's 8px radius is
 * --radius-lg here (upstream --radius-lg is also 0.5rem).
 *
 * ui-sdk renders the content in the browser's top layer with no positioner
 * element, so the content keeps upstream's z-index directly.
 *
 * Upstream has no arrow part and no arrow rule, so ui-sdk's HoverCardArrow
 * ships unstyled.
 *
 * hover-card.css has no [data-color-scheme="dark"] block upstream: the --v2-*
 * tokens flip with the scheme.
 *
 * The rule set is attribute driven, so the React, Vue and web-component
 * bindings can reuse this file unchanged.
 */

@layer components {
  [data-slot="hover-card-trigger"] {
    display: flex;
    width: 100%;
    min-width: 0;
  }

  [data-slot="hover-card-content"] {
    z-index: 50;
    min-width: 200px;
    max-width: 320px;
    max-height: calc(100vh - 1rem);
    padding: 4px;
    overflow: hidden;
    border-radius: var(--radius-lg);

    /* upstream --surface-raised-stronger-non-alpha (#fff light); the floating
       layer is the nearest --v2-* token, as in popover and tooltip */
    background-color: var(--v2-background-bg-layer-01);

    pointer-events: auto;

    border: 1px solid var(--v2-border-border-muted);
    background-clip: padding-box;

    /* upstream --shadow-md */
    box-shadow: var(--v2-elevation-floating);

    transform-origin: var(--transform-origin);
  }

  [data-slot="hover-card-content"]:focus-within {
    outline: none;
  }

  [data-slot="hover-card-content"]:is([data-closed], [data-ending-style]) {
    animation: hover-card-close 0.15s ease-out;
  }

  [data-slot="hover-card-content"][data-open] {
    animation: hover-card-open 0.15s ease-out;
  }

  @keyframes hover-card-open {
    from {
      opacity: 0;
      transform: scale(0.96);
    }

    to {
      opacity: 1;
      transform: scale(1);
    }
  }

  @keyframes hover-card-close {
    from {
      opacity: 1;
      transform: scale(1);
    }

    to {
      opacity: 0;
      transform: scale(0.96);
    }
  }
}
